import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"To approve","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/direction/a-approuver.md","filePath":"src/en/guide/direction/a-approuver.md"}'),n={name:"en/guide/direction/a-approuver.md"};function s(i,e,h,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="to-approve" tabindex="-1">To approve <a class="header-anchor" href="#to-approve" aria-label="Permalink to &quot;To approve&quot;">​</a></h1><p>The <strong>To approve</strong> page gathers everything waiting on <strong>your</strong> decision: expenses, student site transfers, staff transfers. It is made for a phone: each request fits on one card, with its buttons. It opens first in the <strong>Direction</strong> space of the menu, or from <strong>Home</strong> for an administrator.</p><h2 id="what-you-find-there" tabindex="-1">What you find there <a class="header-anchor" href="#what-you-find-there" aria-label="Permalink to &quot;What you find there&quot;">​</a></h2><p>Only what you may decide yourself:</p><ul><li>a <strong>site director</strong> sees their sites&#39; expenses up to the <a href="/era-guide/en/guide/direction/#expenses">threshold</a>, the staff transfers touching one of their sites, and their sites&#39; side of student transfers;</li><li>the <strong>general director</strong> and the <strong>administrator</strong> see everything;</li><li>the <strong>secretariat</strong> sees the student-transfer side of the sites that have no director.</li></ul><p>A transfer whose side you have already approved is no longer listed: it is waiting on the other site. An expense above the threshold does not appear for a site director, since the general direction decides it.</p><h2 id="deciding" tabindex="-1">Deciding <a class="header-anchor" href="#deciding" aria-label="Permalink to &quot;Deciding&quot;">​</a></h2><ul><li><strong>Approve</strong> settles the request in one gesture.</li><li><strong>Reject</strong> asks for a reason, passed on to the requester.</li><li><strong>Details</strong> opens the request&#39;s full page.</li></ul><p>A decided request leaves the list straight away.</p><h3 id="welcoming-a-student" tabindex="-1">Welcoming a student <a class="header-anchor" href="#welcoming-a-student" aria-label="Permalink to &quot;Welcoming a student&quot;">​</a></h3><p>For a transfer, the departure site <strong>approves the departure</strong>, the arrival site <strong>approves the arrival</strong>. Approving the arrival asks for the class: only the classes of the right department, on the arrival site and in the current year, are offered, with their headcount (for instance <em>6e A (30/30)</em>).</p><p>To place the student in a full class, tick <strong>Force the assignment</strong> and give the reason. The override is recorded and shows on the <a href="/era-guide/en/guide/direction/pilotage.html#classes-over-capacity">Pilotage</a> page.</p><p>The transfer is carried out once both sites have approved, in either order.</p><h2 id="the-money-at-a-glance" tabindex="-1">The money at a glance <a class="header-anchor" href="#the-money-at-a-glance" aria-label="Permalink to &quot;The money at a glance&quot;">​</a></h2><p>At the top of the page, the direction and the administrator see, over their sites and for the year chosen in the header:</p><ul><li>what was <strong>Collected</strong> and <strong>Disbursed</strong> this month;</li><li>the year&#39;s <strong>Collection</strong> rate, with the amount still to collect;</li><li>the total of the <strong>Expenses to decide</strong> waiting on you.</li></ul><p>The <strong>Open the pilotage</strong> link leads to the details.</p><h2 id="from-a-notification" tabindex="-1">From a notification <a class="header-anchor" href="#from-a-notification" aria-label="Permalink to &quot;From a notification&quot;">​</a></h2><p>Turn notifications on in <strong>Settings → Notifications</strong>. Each new request then reaches your phone; a tap opens the <strong>To approve</strong> page with that request outlined.</p><p>If someone decided it in the meantime, a message says so, with an <strong>Open the request</strong> link to see what was decided.</p>',20)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
